package workerclient

// hmacvectors_test.go — THE SIGNATURE VECTORS: generated by running the
// unmodified reference's CloudflareSync._sign_request at rev 98f4fc7
// (the SESSION-014 venv run, time.time monkeypatched to fixed instants —
// static facts, byte-compared against the Go port's SignHeaders).

import (
	"fmt"
	"testing"
)

const (
	vecInstall = "11111111-2222-3333-4444-555555555555"
	vecSecret  = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
)

// The bodies are Python json.dumps output (the ", "/": " separators)
// — the EXACT wire bytes the signatures cover.
var hmacVectors = []struct {
	method, path, body string
	ts                 int64
	sig                string
}{
	{
		"GET",
		"/api/pending",
		"{}",
		1760000000500,
		"c414e713ef6becb9ff0545b0f450f0ca5b6b09f05ab5553be4481c6413396220",
	},
	{
		"POST",
		"/api/vault_mirror/push",
		"{\"install_id\": \"11111111-2222-3333-4444-555555555555\", \"sync_id\": \"0f0e0d0c-0b0a-4903-8802-1f2e3d4c5b6a\", \"vault_index_hash\": \"deadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeef\", \"entries\": [{\"url_normalized\": \"https://example.com/x\", \"vault_path\": \"a/b.md\", \"category\": \"Cat\", \"title\": \"T\", \"status\": \"in_vault\", \"first_processed_at\": \"2026-01-01T00:00:00\", \"last_updated_at\": \"2026-01-02T00:00:00\"}], \"decommission_events\": []}",
		1760000001250,
		"453840aff1efb4c682f82472122a9276a47423dc9582f8750244ae51a8c39789",
	},
	{
		"GET",
		"/api/banish/status?id=abc-123",
		"{}",
		1759999999750,
		"dc1beeddf6ed11623944ab9f6a42675400f28667385a5672dea8d07446051d30",
	},
	{
		"POST",
		"/api/decommission",
		"{\"install_id\": \"11111111-2222-3333-4444-555555555555\", \"url_normalized\": \"https://Example.COM/Path/\", \"reason\": \"404\", \"details\": \"HTTP 404\"}",
		1760000002125,
		"51c92bd9029001fb6439d32c13e20b6d0728273af4a64def9734f6104dc720b4",
	},
	{
		"GET",
		"/api/decommissions?since=1970-01-01T00:00:00Z",
		"{}",
		1760000003000,
		"13495d86062a6d68a52f156156296ac58bb2b61c28ad579ebf8ea5a1e6df90ea",
	},
}

func TestSignatureVectors(t *testing.T) {
	for i, v := range hmacVectors {
		v := v
		t.Run(fmt.Sprintf("case%d_%s", i, v.method), func(t *testing.T) {
			s := NewSync(map[string]any{
				"cloudflare_install_id":    vecInstall,
				"cloudflare_shared_secret": vecSecret,
			})
			saved := nowMS
			nowMS = func() int64 { return v.ts }
			t.Cleanup(func() { nowLog := saved; nowMS = nowLog })
			h := s.SignHeaders(v.method, v.path, v.body)
			if got, _ := h.Get("X-Auth-Install"); got != vecInstall {
				t.Errorf("install = %v", got)
			}
			if got, _ := h.Get("X-Auth-Timestamp"); got != fmt.Sprintf("%d", v.ts) {
				t.Errorf("timestamp = %v, want %d", got, v.ts)
			}
			if got, _ := h.Get("X-Auth-Signature"); got != v.sig {
				t.Errorf("signature = %v\n  want   %v", got, v.sig)
			}
			if got, _ := h.Get("Content-Type"); got != "application/json" {
				t.Errorf("content-type = %v", got)
			}
			if got, _ := h.Get("User-Agent"); got != HTTPUserAgent {
				t.Errorf("user-agent = %v", got)
			}
		})
	}
}
